	if err = randomize.Struct(seed, &o, configAtualizacaoDBTypes, false); err != nil {
		t.Errorf("Unable to randomize ConfigAtualizacao struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Upsert(ctx, tx, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert ConfigAtualizacao: %s", err)
	}

	count, err := ConfigAtualizacaos().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}

	// Attempt the UPDATE side of an UPSERT
	if err = randomize.Struct(seed, &o, configAtualizacaoDBTypes, false, configAtualizacaoPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize ConfigAtualizacao struct: %s", err)
	}

	if err = o.Upsert(ctx, tx, boil.Infer(), boil.Infer()); err != nil {
		t.Errorf("Unable to upsert ConfigAtualizacao: %s", err)
	}

	count, err = ConfigAtualizacaos().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}
	if count != 1 {
		t.Error("want one record, got:", count)
	}
